//! Bit-exact parity with Go for labelgeom.ArrowheadTopLeft, label.Position
//! GetPointOnRoute/GetPointOnBox/metadata and assorted geo functions.
//! Fixture: tests/fixtures/go-unit/labels.txt, generated by goref/base-parity/labels
//! (`scripts/gen-goref.sh`).
#![allow(non_snake_case)]
extern crate orthoflow_labelgeom as labelgeom;
use geo::{PointRef, PointsExt, RouteExt, Segment, VectorExt};

fn h(f: f64) -> String {
    format!("{:016x}", f.to_bits())
}
fn fh(s: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(s, 16).unwrap())
}
fn pt(p: Option<&PointRef>) -> String {
    match p {
        None => "nil".into(),
        Some(p) => {
            let p = p.get();
            format!("{},{}", h(p.X), h(p.Y))
        }
    }
}
fn ppt(s: &str) -> PointRef {
    let (x, y) = s.split_once(',').unwrap();
    geo::NewPoint(fh(x), fh(y))
}
fn proute(s: &str) -> Vec<PointRef> {
    s.split(';').map(ppt).collect()
}
fn route(r: &[PointRef]) -> String {
    r.iter().map(|p| pt(Some(p))).collect::<Vec<_>>().join(";")
}

/// NaN payload/sign is not reproducible across compilers (operand commutation,
/// constant folding); every NaN compares equal here. See DEVIATIONS.md.
fn norm_nan(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if i + 16 <= b.len() && (i == 0 || !b[i - 1].is_ascii_hexdigit()) && b[i..i + 16].iter().all(|c| c.is_ascii_hexdigit()) && (i + 16 == b.len() || !b[i + 16].is_ascii_hexdigit()) {
            let v = f64::from_bits(u64::from_str_radix(&s[i..i + 16], 16).unwrap());
            if v.is_nan() {
                out.push_str("NaN");
            } else {
                out.push_str(&s[i..i + 16]);
            }
            i += 16;
        } else {
            out.push(b[i] as char);
            i += 1;
        }
    }
    out
}

#[test]
fn labels_parity() {
    let dir = std::fs::canonicalize(env!("CARGO_MANIFEST_DIR")).unwrap();
    let data = std::fs::read_to_string(dir.join("../../tests/fixtures/go-unit/labels.txt")).expect("fixture");
    let mut n = 0;
    let mut fails: Vec<String> = Vec::new();
    for line in data.lines() {
        let f: Vec<&str> = line.split(' ').collect();
        let got = match f[0] {
            "arrow" => {
                let rt = proute(f[1]);
                let isT = f[2] == "true";
                let p = labelgeom::ArrowheadTopLeft(&rt, isT, f[3], f[4], fh(f[5]), fh(f[6]));
                format!("arrow {} {} {} {} {} {} => {}", route(&rt), isT, f[3], f[4], f[5], f[6], pt(Some(&p)))
            }
            "onroute" => {
                let rt = proute(f[1]);
                let pos = label::Position(f[2].parse().unwrap());
                let (p, idx) = pos.GetPointOnRoute(&rt, fh(f[3]), fh(f[4]), fh(f[5]), fh(f[6]));
                format!("onroute {} {} {} {} {} {} => {} {}", route(&rt), pos.0, f[3], f[4], f[5], f[6], pt(p.as_ref()), idx)
            }
            "onbox" => {
                let b = geo::Box::new(ppt(f[1]), fh(f[2]), fh(f[3]));
                let pos = label::Position(f[5].parse().unwrap());
                let q = pos.GetPointOnBox(&b, fh(f[4]), fh(f[6]), fh(f[7]));
                format!("onbox {} {} {} {} {} {} {} {} => {}", f[1], f[2], f[3], f[4], pos.0, f[6], f[7], pos.String(), pt(Some(&q)))
            }
            "posmeta" => {
                let pos = label::Position(f[1].parse().unwrap());
                format!(
                    "posmeta {} {} {} {} {} {} {} {} {}",
                    pos.0,
                    pos.IsShapePosition(),
                    pos.IsEdgePosition(),
                    pos.IsOutside(),
                    pos.IsUnlocked(),
                    pos.IsBorder(),
                    pos.IsOnEdge(),
                    pos.Mirrored().0,
                    label::FromString(&pos.String()).0
                )
            }
            "route" => {
                let rt = proute(f[1]);
                let d = fh(f[2]);
                let (tl, br) = rt.GetBoundingBox();
                let (p, idx) = rt.GetPointAtDistance(d);
                format!(
                    "route {} {} => {} {} {} {} {} {}",
                    route(&rt),
                    f[2],
                    h(rt.Length()),
                    pt(Some(&tl)),
                    pt(Some(&br)),
                    pt(Some(&p)),
                    idx,
                    pt(Some(&rt.GetMedian()))
                )
            }
            "geo" => {
                let (a, b, c, e) = (ppt(f[1]), ppt(f[2]), ppt(f[3]), ppt(f[4]));
                let ip = geo::IntersectionPoint(&a, &b, &c, &e);
                let cv = c.get();
                format!(
                    "geo {} {} {} {} => {} {} {} {} {} {}",
                    f[1],
                    f[2],
                    f[3],
                    f[4],
                    pt(ip.as_ref()),
                    h(c.DistanceToLine(&a, &b)),
                    a.GetOrientation(&b).0,
                    a.Compare(&c),
                    h(geo::TruncateDecimals(cv.X)),
                    h(vec![cv.X, cv.Y].Radians())
                )
            }
            "bezier" => {
                let pts = proute(f[1]);
                let t = fh(f[2]);
                let sp = proute(f[3]);
                let bc = geo::NewBezierCurve(&pts);
                let seg = Segment::new(sp[0].clone(), sp[1].clone());
                let is: Vec<String> = bc.Intersections(&seg).iter().map(|q| pt(Some(q))).collect();
                format!("bezier {} {} {} => {} [{}]", route(&pts), f[2], f[3], pt(Some(&bc.At(t))), is.join("|"))
            }
            other => panic!("unknown {other}"),
        };
        if norm_nan(&got) != norm_nan(line) {
            fails.push(format!("want {line}\n got {got}"));
        }
        n += 1;
    }
    assert!(fails.is_empty(), "{} failures; first: {:#?}", fails.len(), &fails[..fails.len().min(8)]);
    assert!(n > 13000);
}
